select budget_bucket, dept_name, avg_budget, tokyo_count from (select case when budget >= 4171000 then 'high' when budget >= 1073000 then 'mid' else 'low' end as budget_bucket, dept_name, round(avg(budget), 2) as avg_budget, count(case when location = 'Tokyo' then 1 end) as tokyo_count from departments group by case when budget >= 4171000 then 'high' when budget >= 1073000 then 'mid' else 'low' end, dept_name) as t where tokyo_count < 8;
